 private bool solarWorldPane=true;private string solarPage="Observations",solarProject="Sun";private long solarFaction,solarHost;private int solarModeChoice,solarSeason=12;
 private long CampaignActor=>selection.FirstOrDefault(id=>world.Colony.People.ContainsKey(id)&&world.CanAct(id)&&!world.Colony.People[id].Drafted) is var chosen&&chosen!=0?chosen:world.Colony.People.Keys.FirstOrDefault(id=>world.CanAct(id)&&!world.Colony.People[id].Drafted);
 private void DrawSolarCampaign(Rectangle p)
 {
  int x=p.X+18,y=p.Y+50;string[] pages=["Observations","Projects","Politics","Director"];for(int n=0;n<4;n++){string page=pages[n];Button(new(x+n*152,y,142,26),page,()=>solarPage=page,solarPage==page,scale:.66f);}y+=36;
  switch(solarPage){case "Projects":DrawSolarProjects(p,x,y);return;case "Politics":DrawSolarPolitics(p,x,y);return;case "Director":DrawSolarDirector(p,x,y);return;}
  var s=world.Solar;Label((s.Mode=="Open Twilight"?"Open Twilight":World.SolarStages[s.Stage])+" | luminosity "+s.Luminosity+" | instability "+s.Instability+" | refuge beds "+world.RefugeCapacity()+" | outcome "+(s.Finale==""?"Open":s.Finale),x,y,Cyan,.7f);y+=30;
  Paragraph(world.SolarRules(),new(x,y,p.Width-36,48),Muted,.68f);y+=54;
  string chosen=World.SolarModes[solarModeChoice];Button(new(x,y,125,26),"Next mode",()=>solarModeChoice=(solarModeChoice+1)%4,scale:.65f);Label(chosen,x+136,y+4,Gold,.7f);Button(new(x+315,y,160,26),"Season: "+solarSeason+" days",()=>solarSeason=solarSeason>=60?2:solarSeason+2,scale:.63f);Button(new(x+485,y,205,26),"Apply campaign mode",()=>Execute(new(CommandKind.CampaignAction,DefinitionId:World.SolarModes[solarModeChoice],Quantity:solarSeason,Text:"mode")),hint:"Slow Dusk: 12 days per stage. Last Century: 6. Custom: displayed 2–60. Open Twilight disables decline. Existing people/terrain remain.",scale:.64f);y+=36;
  Label("Next boundary: "+(s.Mode=="Open Twilight"||s.Stage==4||s.SunRestored?"No further decline":"day "+(s.NextBoundary/World.TicksPerDay+1))+" | next flare: "+(s.NextFlareAt==0?"none scheduled":"day "+(s.NextFlareAt/World.TicksPerDay+1)+" hour "+(s.NextFlareAt%World.TicksPerDay/World.TicksPerHour)),x,y,Text,.65f);y+=27;
  foreach(var forecast in s.Forecasts.AsEnumerable().Reverse().Skip(rowOffset).Take(2)){Paragraph((forecast.Resolved?"Recorded: ":"WARNING: ")+forecast.Text,new(x,y,p.Width-36,48),forecast.Resolved?Muted:Gold,.65f);y+=52;}
  if(s.Forecasts.Count==0){Paragraph("No forecast pending. Surface crops and solar panels respond to measured sunlight. Artificial light, heated greenhouses and fungi are existing alternatives. Pack cloth or delay travel during warned flares.",new(x,y,p.Width-36,48),Muted,.66f);y+=53;}
  Label("Regional adaptations: "+string.Join(" | ",s.Refuges.Select(r=>world.Region.Factions.First(f=>f.Id==r.FactionId).Name.Split(' ')[0]+" L"+r.Level)),x,y,Cyan,.63f);
 }
 private void DrawSolarProjects(Rectangle p,int x,int y)
 {
  var all=world.Solar.Projects;var project=all.First(a=>a.Id==solarProject);int index=Array.IndexOf(World.FinaleIds,solarProject);Button(new(x,y,310,27),World.FinaleNames[index],()=>{solarProject=World.FinaleIds[(index+1)%5];solarHost=0;},scale:.66f);Button(new(x+320,y,170,27),"Locate assigned host",()=>{if(project.HostId!=0)Focus(project.HostId);else status="Choose a suitable host first.";},scale:.63f);y+=36;
  string kind=solarProject=="Sun"?"relic":solarProject=="Vessel"?"workbench":"study";var hosts=world.Entities.Where(e=>e.DefinitionId==kind&&!e.Forbidden).OrderBy(e=>e.Id).ToArray();if(!hosts.Any(e=>e.Id==solarHost))solarHost=hosts.FirstOrDefault()?.Id??0;
  Button(new(x,y,275,27),"Host: "+(world.Find(solarHost) is {} chosenHost?chosenHost.Name+" | level "+chosenHost.Z:"Build "+kind),()=>{if(hosts.Length>0)solarHost=hosts[(Array.FindIndex(hosts,e=>e.Id==solarHost)+1)%hosts.Length].Id;},scale:.64f);Button(new(x+285,y,185,27),"Commission project",()=>Execute(new(CommandKind.CampaignAction,CampaignActor,solarProject,TargetId:solarHost,Text:"project")),hint:"Select a preferred undrafted worker on the map. Return expeditions. This assigns real hauling/work; requirements are checked again at each phase.",scale:.64f);Button(new(x+480,y,150,27),"Pause project",()=>Execute(new(CommandKind.CampaignAction,DefinitionId:solarProject,Text:"pause-project")),scale:.64f);y+=36;
  Label("Phase "+project.Phase+"/3 | work "+project.Work+"/90 | "+project.Status,x,y,project.Completed?Cyan:Gold,.65f);y+=28;
  var preview=new CampaignProject{Id=project.Id,HostId=solarHost,Phase=project.Phase};var missing=world.ProjectMissing(preview);Paragraph(project.Completed?"Campaign finale completed and recorded. Its material ledger and outcome persist; continuing residents still need real food, care and power.":missing.Count==0?"All prerequisites met. Assign Construct or Research work; materials are collected normally.":"Requirements: "+string.Join("; ",missing),new(x,y,p.Width-36,72),Muted,.65f);y+=77;
  Label((project.Completed?"Final phase paid: ":"Next phase materials: ")+string.Join(", ",world.ProjectIngredients(project.Id,Math.Min(2,project.Phase)).Select(k=>k.Value+" "+k.Key)),x,y,Text,.64f);y+=28;
  Label("Consumed ledger: "+(project.Spent.Count==0?"none":string.Join(", ",project.Spent.Select(k=>k.Value+" "+k.Key))),x,y,Cyan,.64f);y+=29;
  Paragraph("Sun restores regional light and climate. Vessel boards the living roster. Ark preserves a real underground refuge. Federation pools actual allied reserves. Archive records learned knowledge and keeps refuge play open. One finale per campaign; declining every project is permitted.",new(x,y,p.Width-36,72),Muted,.66f);
 }
 private void DrawSolarPolitics(Rectangle p,int x,int y)
 {
  if(!world.Region.Factions.Any(f=>f.Id==solarFaction))solarFaction=world.Region.Factions[1].Id;var f=world.Region.Factions.First(f=>f.Id==solarFaction);Button(new(x,y,330,27),f.Name,()=>solarFaction=world.Region.Factions[(world.Region.Factions.IndexOf(f)+1)%6].Id,scale:.64f);y+=36;
  var party=world.Region.Parties.FirstOrDefault(p=>p.State=="AtSite"&&p.SiteId==world.Region.Sites.First(s=>s.Kind=="Town"&&s.FactionId==f.Id).Id);long envoy=party?.Members.FirstOrDefault(id=>world.CanAct(id))??0;
  Button(new(x,y,220,27),"Accept scholarly patron",()=>Execute(new(CommandKind.CampaignAction,envoy,"Open access",TargetId:f.Id,Text:"patron")),hint:"At its town counter: receive six real meals and six parts, plus title. Four new library sessions with Open archive are due every seven days.",scale:.63f);Button(new(x+230,y,220,27),"Accept supply patron",()=>Execute(new(CommandKind.CampaignAction,envoy,"Supplies",TargetId:f.Id,Text:"patron")),hint:"Same funded aid; three packed brass is owed at the town counter every seven days.",scale:.63f);y+=36;
  var pact=world.Solar.Patrons.FirstOrDefault(p=>p.FactionId==f.Id);if(pact!=null){Label(pact.Title+" | "+pact.Demand+" | due day "+(pact.DueAt/World.TicksPerDay+1)+" | "+pact.Result,x,y,Gold,.65f);y+=28;Button(new(x,y,170,26),"Fulfill obligation",()=>Execute(new(CommandKind.CampaignAction,envoy,TargetId:pact.Id,Text:"fulfill")),scale:.64f);Button(new(x+180,y,175,26),"Refuse patronage",()=>Execute(new(CommandKind.CampaignAction,TargetId:pact.Id,Text:"refuse-patron")),hint:"Title withdrawn, grievance +10, trust -5. Independent finales remain available.",scale:.64f);y+=36;}
  var claim=world.Solar.Claims.FirstOrDefault(c=>c.FactionId==f.Id);if(claim!=null){Paragraph("Sanctuary: "+claim.State+" | "+claim.Result+". Share requires a capable resident beside a study desk and two spare dry, warm beds. Refusal adds twenty grievance; diplomacy still controls raid eligibility.",new(x,y,p.Width-36,70),Muted,.65f);y+=75;Button(new(x,y,195,27),"Share two refuge places",()=>Execute(new(CommandKind.CampaignAction,CampaignActor,TargetId:claim.Id,Text:"share-refuge")),scale:.63f);Button(new(x+205,y,205,27),"Choose independence",()=>Execute(new(CommandKind.CampaignAction,TargetId:claim.Id,Text:"refuse-claim")),scale:.63f);}
  else Paragraph("No sanctuary demand from this faction. Patrons and claims come from persistent regional motives. Titles grant funded help and explicit obligations; no finale requires a title. Signed peaceful agreements are respected by conflict eligibility.",new(x,y,p.Width-36,70),Muted,.66f);
 }
 private void DrawSolarDirector(Rectangle p,int x,int y)
 {
  var s=world.Solar;Button(new(x,y,330,27),s.Director,()=>Execute(new(CommandKind.CampaignAction,DefinitionId:World.Directors[(Array.IndexOf(World.Directors,s.Director)+1)%3],Text:"director")),scale:.65f);y+=36;
  string[] names=["Raids","Scarcity","Instability","Disease","Stress"];int[] values=[s.RaidIntensity,s.Scarcity,s.InstabilitySetting,s.Disease,s.Stress];for(int n=0;n<5;n++){string name=names[n];int value=values[n];Button(new(x+n*136,y,126,27),name+": "+value,()=>Execute(new(CommandKind.CampaignAction,DefinitionId:name,Quantity:value>=100?0:Math.Min(100,value+25),Text:"setting")),hint:"Independent explicit setting, 0–100. Changing it does not reset people, terrain or solar stage.",scale:.62f);}y+=36;
  Paragraph(s.DirectorStatus+" | Eligibility: "+(world.CampaignRecoveryReason() is var reason&&reason!=""?reason:"Recovery checks clear; funded persistent hostile motive still required"),new(x,y,p.Width-36,48),Cyan,.66f);y+=54;
